def test_reducer_accepts_only_evidence_backed_findings() -> None:
    receipt = validate_contract_receipt(
        {
            "scope": "correctness_regression",
            "verdict": "NEEDS_CHANGES",
            "summary": "One grounded issue and one unsupported concern.",
            "blocking_findings": [
                {
                    "id": "CR-1",
                    "severity": "major",
                    "file": "src/app.py",
                    "lines": "12",
                    "evidence": "src/app.py:12 calls do_work(None) after validation removed.",
                    "claim": "None input now reaches do_work.",
                    "impact": "Crashes existing empty-input path.",
                    "suggested_fix": "Restore the empty-input guard.",
                    "confidence": "high",
                },
                {
                    "id": "CR-2",
                    "severity": "major",
                    "file": "",
                    "lines": "",
                    "evidence": "none",
                    "claim": "This feels wrong.",
                    "impact": "Unproven.",
                    "suggested_fix": "Rewrite it.",
                    "confidence": "low",
                },
            ],
            "non_blocking_findings": [],
            "unsupported_or_rejected_concerns": [],
            "evidence_checked": [{"type": "file", "reference": "src/app.py", "result": "checked"}],
            "missing_evidence": [],
        },
        "correctness_regression",
    )

    aggregate = reduce_contract_receipts([receipt])

    assert aggregate["verdict"] == "NEEDS_CHANGES"
    assert len(aggregate["accepted_blocking_findings"]) == 1
    assert aggregate["accepted_blocking_findings"][0]["id"] == "CR-1"
    assert len(aggregate["unsupported_or_rejected_concerns"]) == 1
    assert aggregate["unsupported_or_rejected_concerns"][0]["claim"] == "This feels wrong."


def test_blocked_scope_fails_closed_even_without_findings() -> None:
    receipt = validate_contract_receipt(
        {
            "scope": "tests_validation",
            "verdict": "BLOCKED",
            "summary": "Validation log missing.",
            "blocking_findings": [],
            "non_blocking_findings": [],
            "unsupported_or_rejected_concerns": [],
            "evidence_checked": [],
            "missing_evidence": ["pytest output for changed parser"],
        },
        "tests_validation",
    )

    aggregate = reduce_contract_receipts([receipt])

    assert aggregate["verdict"] == "BLOCKED"
    assert aggregate["missing_evidence"] == [
        {"scope": "tests_validation", "missing": "pytest output for changed parser"}
    ]


def test_finding_without_file_or_evidence_is_not_accepted() -> None:
    assert not finding_has_concrete_evidence({"file": "src/app.py", "evidence": "", "claim": "bad"})
    assert not finding_has_concrete_evidence({"file": "", "evidence": "log line", "claim": "bad"})
    assert finding_has_concrete_evidence({"file": "src/app.py", "evidence": "src/app.py:1", "claim": "bad"})
